<template><section class="space-y-6"><div class="flex justify-end"><button class="btn-muted" @click="$emit('toggle-editing')"><i class="fa-solid fa-pen mr-2"></i>{{ editing ? "Discard changes" : "Edit project" }}
      </button></div><form v-if="editing" class="panel grid gap-4 p-5 md:grid-cols-2" @submit.prevent="$emit('save-project')"><label class="block text-sm font-semibold">Title<input v-model.trim="draft.title" class="field mt-2" required /></label><label class="block text-sm font-semibold">Category<input v-model.trim="draft.category" class="field mt-2" required /></label><label class="block text-sm font-semibold">Budget<input v-model.number="draft.budget" class="field mt-2" type="number" min="1" required /></label><label class="block text-sm font-semibold">
        Status
        <select v-model="draft.status" class="field mt-2"><option>OPEN</option><option>DRAFT</option><option>IN_PROGRESS</option><option>COMPLETED</option></select></label><label class="block text-sm font-semibold">Due date<input v-model="draft.dueDate" class="field mt-2" type="date" /></label><label class="block text-sm font-semibold">Skills <span class="font-normal text-slate-400">(comma separated)</span><input v-model="draft.skillsText" class="field mt-2" /></label><label class="block text-sm font-semibold md:col-span-2">Description<textarea v-model.trim="draft.description" class="field mt-2 min-h-28" placeholder="Describe the project scope"></textarea></label><div class="flex justify-end gap-3 md:col-span-2"><button type="button" class="btn-muted" @click="$emit('reset-draft')">Cancel</button><button class="btn-brand">Save changes</button></div></form><div class="grid gap-6 lg:grid-cols-[1.25fr_.75fr]"><div class="space-y-6"><article class="panel p-5"><h2 class="text-lg font-800">Delivery progress</h2><div class="mt-4 h-2 overflow-hidden rounded-full bg-slate-100 dark:bg-slate-700"><div class="h-full rounded-full bg-brand transition-all" :style="{ width: `${job.progress || 0}%` }"></div></div><p class="mt-2 text-sm text-slate-500">{{ job.progress || 0 }}% complete</p><div class="mt-6 grid gap-4 sm:grid-cols-2"><div><p class="text-xs font-bold uppercase tracking-wide text-slate-400">Skills</p><div class="mt-2 flex flex-wrap gap-2"><span v-for="skill in job.skills || []" :key="skill" class="badge bg-slate-100 text-slate-600 dark:bg-slate-700 dark:text-slate-200">{{ skill }}</span></div></div><div><p class="text-xs font-bold uppercase tracking-wide text-slate-400">Owner</p><RouterLink :to="`/profile/${job.clientId}`" class="mt-2 inline-block font-semibold text-brand hover:underline">{{ userName(job.clientId) || "Unassigned" }}</RouterLink></div></div></article><article class="panel p-5"><h2 class="text-lg font-800">Latest activity</h2><div v-if="comments.length" class="mt-4 space-y-3"><div v-for="comment in comments.slice(-3).reverse()" :key="comment.id" class="rounded-xl bg-slate-50 p-4 dark:bg-slate-800/65"><b>{{ userName(comment.userId) }}</b><p class="mt-1 text-sm text-slate-600 dark:text-slate-300">{{ comment.text }}</p><small class="mt-2 block text-slate-400">{{ formatDate(comment.at) }}</small></div></div><p v-else class="mt-4 text-sm text-slate-500">No project updates yet.</p></article></div><aside class="space-y-4"><article class="panel p-5"><p class="text-xs font-bold uppercase tracking-wide text-slate-400">Commercial summary</p><b class="mt-2 block text-2xl">{{ formatMoney(job.budget, job.currency) }}</b><p class="mt-2 text-sm text-slate-500">{{ proposalsCount }} {{ proposalsCount === 1 ? "provider proposal" : "provider proposals" }}</p></article><RouterLink v-if="job.contractId" class="btn-muted w-full" :to="`/contract/${job.contractId}`"><i class="fa-solid fa-file-contract mr-2"></i>View contract</RouterLink><RouterLink v-if="job.contestId" class="btn-muted w-full" :to="`/project/${job.id}/contest`"><i class="fa-solid fa-trophy mr-2"></i>Open contest</RouterLink></aside></div></section></template>
<script>
export default {
props: {
job: Object,
draft: Object,
editing: Boolean,
comments: Array,
proposalsCount: Number,
userName: Function,
formatDate: Function,
formatMoney: Function,
},
